#ifndef ZOVUTILS_EXPR_BACKEND_H
#define ZOVUTILS_EXPR_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <regex.h>
typedef struct{const char**v;int n,p,err;} zov_expr;
typedef struct{char*s;} zov_ev;
static inline char*ze_dup(const char*s){size_t n=strlen(s?s:"");char*p=(char*)malloc(n+1);if(p)memcpy(p,s?s:"",n+1);return p;}
static inline zov_ev zev(const char*s){zov_ev r;r.s=ze_dup(s?s:"");return r;}
static inline int ze_truth(zov_ev a){return a.s&&a.s[0]&&strcmp(a.s,"0")!=0;}
static inline int ze_num(zov_ev a,int64_t*out){if(!a.s||!a.s[0])return 0;char*e;errno=0;long long n=strtoll(a.s,&e,10);if(errno||*e)return 0;*out=(int64_t)n;return 1;}
static inline zov_ev ze_fmt(int64_t n){char b[64];snprintf(b,sizeof b,"%lld",(long long)n);return zev(b);}
static inline zov_ev ze_or(zov_expr*,int);static inline zov_ev ze_primary(zov_expr*e){if(e->p>=e->n){e->err=1;return zev("");}const char*t=e->v[e->p++];if(!strcmp(t,"(")){zov_ev x=ze_or(e,0);if(e->p>=e->n||strcmp(e->v[e->p],")")){e->err=1;}else e->p++;return x;}if(!strcmp(t,"length")||!strcmp(t,"quote")){if(e->p>=e->n){e->err=1;return zev("");}const char*s=e->v[e->p++];if(!strcmp(t,"quote"))return zev(s);return ze_fmt((int64_t)strlen(s));}if(!strcmp(t,"substr")||!strcmp(t,"index")||!strcmp(t,"match")){if(e->p+1>=e->n){e->err=1;return zev("");}const char*a=e->v[e->p++],*b=e->v[e->p++];if(!strcmp(t,"substr")){if(e->p>=e->n){e->err=1;return zev("");}char*end;long p=strtol(b,&end,10);if(*end){e->err=1;return zev("");}long n=strtol(e->v[e->p++],&end,10);if(*end){e->err=1;return zev("");}size_t len=strlen(a);if(p<1)p=1;if((size_t)(p-1)>=len||n<=0)return zev("");size_t take=len-(size_t)(p-1);if((size_t)n<take)take=(size_t)n;char*out=(char*)malloc(take+1);if(!out){e->err=1;return zev("");}memcpy(out,a+p-1,take);out[take]=0;zov_ev r={out};return r;}if(!strcmp(t,"index")){long pos=0;for(size_t i=0;a[i]&&!pos;i++)for(size_t j=0;b[j];j++)if(a[i]==b[j]){pos=(long)i+1;break;}return ze_fmt(pos);}regex_t rx;if(regcomp(&rx,b,0)){e->err=1;return zev("");}regmatch_t m[2];int rc=regexec(&rx,a,2,m,0);zov_ev r;if(rc){r=zev("0");}else if(!strcmp(t,"match")){if(m[1].rm_so>=0) {size_t n=(size_t)(m[1].rm_eo-m[1].rm_so);char*out=(char*)malloc(n+1);memcpy(out,a+m[1].rm_so,n);out[n]=0;r.s=out;}else r=ze_fmt((int64_t)m[0].rm_eo);}else r=ze_fmt((int64_t)m[0].rm_eo);regfree(&rx);return r;}return zev(t);}
static inline zov_ev ze_match(zov_expr*e){zov_ev a=ze_primary(e);while(e->p<e->n&&!strcmp(e->v[e->p],":")){e->p++;if(e->p>=e->n){e->err=1;return a;}const char*pat=e->v[e->p++];regex_t rx;if(regcomp(&rx,pat,0)){e->err=1;return a;}regmatch_t m[2];int rc=regexec(&rx,a.s,2,m,0);zov_ev r;if(rc)r=zev("0");else if(m[1].rm_so>=0){size_t n=(size_t)(m[1].rm_eo-m[1].rm_so);char*out=(char*)malloc(n+1);memcpy(out,a.s+m[1].rm_so,n);out[n]=0;r.s=out;}else r=ze_fmt((int64_t)m[0].rm_eo);regfree(&rx);free(a.s);a=r;}return a;}
static inline zov_ev ze_mul(zov_expr*e){zov_ev a=ze_match(e);while(e->p<e->n){const char*op=e->v[e->p];if(strcmp(op,"*")&&strcmp(op,"/")&&strcmp(op,"%"))break;e->p++;zov_ev b=ze_match(e);int64_t x,y;if(!ze_num(a,&x)||!ze_num(b,&y)||(y==0&&strcmp(op,"*"))){e->err=1;free(a.s);free(b.s);return zev("0");}int64_t z=!strcmp(op,"*")?x*y:!strcmp(op,"/")?x/y:x%y;free(a.s);free(b.s);a=ze_fmt(z);}return a;}
static inline zov_ev ze_add(zov_expr*e){zov_ev a=ze_mul(e);while(e->p<e->n){const char*op=e->v[e->p];if(strcmp(op,"+")&&strcmp(op,"-"))break;e->p++;zov_ev b=ze_mul(e);int64_t x,y;if(!ze_num(a,&x)||!ze_num(b,&y)){e->err=1;free(a.s);free(b.s);return zev("0");}int64_t z=!strcmp(op,"+")?x+y:x-y;free(a.s);free(b.s);a=ze_fmt(z);}return a;}
static inline zov_ev ze_cmp(zov_expr*e){zov_ev a=ze_add(e);while(e->p<e->n){const char*op=e->v[e->p];if(strcmp(op,"=")&&strcmp(op,"!=")&&strcmp(op,"<")&&strcmp(op,"<=")&&strcmp(op,">")&&strcmp(op,">="))break;e->p++;zov_ev b=ze_add(e);int64_t x,y;int c;if(ze_num(a,&x)&&ze_num(b,&y))c=x<y?-1:x>y?1:0;else c=strcmp(a.s,b.s);int yes=!strcmp(op,"=")?c==0:!strcmp(op,"!=")?c!=0:!strcmp(op,"<")?c<0:!strcmp(op,"<=")?c<=0:!strcmp(op,">")?c>0:c>=0;free(a.s);free(b.s);a=zev(yes?"1":"0");}return a;}
static inline zov_ev ze_and(zov_expr*e){zov_ev a=ze_cmp(e);while(e->p<e->n&&!strcmp(e->v[e->p],"&")){e->p++;zov_ev b=ze_cmp(e);if(ze_truth(a)&&ze_truth(b)){free(b.s);}else{free(a.s);free(b.s);a=zev("0");}}return a;}
static inline zov_ev ze_or(zov_expr*e,int unused){(void)unused;zov_ev a=ze_and(e);while(e->p<e->n&&!strcmp(e->v[e->p],"|")){e->p++;zov_ev b=ze_and(e);if(ze_truth(a))free(b.s);else{free(a.s);a=b;}}return a;}
static inline int zov_expr_run(int argc,char**argv){if(argc==1&&!strcmp(argv[0],"--version")){puts("expr (zovutils) 0.10.23");return 0;}if(argc==1&&!strcmp(argv[0],"--help")){puts("Usage: expr EXPRESSION\n  --help     display this help and exit\n  --version  output version information and exit");return 0;}if(argc==0){fprintf(stderr,"expr: missing operand\nTry 'expr --help' for more information.\n");return 2;}zov_expr e={ (const char**)argv,argc,0,0};zov_ev r=ze_or(&e,0);if(e.p!=e.n)e.err=1;if(e.err){fprintf(stderr,"expr: syntax error: %s\n",e.p<e.n?e.v[e.p]:argv[argc-1]);free(r.s);return 2;}puts(r.s);int status=ze_truth(r)?0:1;free(r.s);return status;}
#endif
